/**
 * Generates a Commander-based Command-Line Interface (CLI) from an OpenAPI specification using ts-morph AST builders.
 *
 * @module vendors/cli/emit
 */
import { posix as path } from "node:path";
import {
	type CodeBlockWriter,
	type Project,
	type SourceFile,
	VariableDeclarationKind,
} from "ts-morph";
import type { GeneratorConfig, PathInfo } from "../../core/types/index.js";
import type { Parameter, SecurityScheme } from "../../core/types/openapi.js";
import { snakeCase } from "../../functions/utils_string.js";
import type { SwaggerParser } from "../../openapi/parse.js";

const SINGLE_QUOTE_ESCAPE = `${String.fromCharCode(92)}'`;
const ESCAPED_NEWLINE = `${String.fromCharCode(92)}n`;

/**
 * Escapes single quotes for safe embedding inside single-quoted TypeScript string literals.
 *
 * @param text - Raw input string.
 * @returns Escaped string.
 */
function escapeSingleQuotes(text: string): string {
	return text.split("'").join(SINGLE_QUOTE_ESCAPE);
}

/**
 * Generates a Command-Line Interface (CLI) client (`cli.ts`) from an OpenAPI specification.
 */
export class CliGenerator {
	/**
	 * Generates the `cli.ts` entrypoint file inside the target output directory using structured ts-morph AST nodes.
	 *
	 * @param project - The `ts-morph` project to create the source file in.
	 * @param parser - The parsed OpenAPI/Swagger specification.
	 * @param _config - Generator configuration options.
	 * @param outputDir - Target directory where `cli.ts` will be written.
	 */
	public generate(
		project: Project,
		parser: SwaggerParser,
		_config: GeneratorConfig,
		outputDir: string,
	): void {
		const cliFile = project.createSourceFile(
			path.join(outputDir, "cli.ts"),
			"",
			{ overwrite: true },
		);

		cliFile.addImportDeclaration({
			moduleSpecifier: "commander",
			namedImports: ["Command", "Option"],
		});

		cliFile.addImportDeclaration({
			moduleSpecifier: "./services/index.js",
			namespaceImport: "services",
		});

		const spec = parser.spec;
		const info = spec.info || { title: "api-cli", version: "1.0.0" };
		const title = info.title || "api-cli";
		const version = info.version || "1.0.0";
		const description = escapeSingleQuotes(
			info.description || info.summary || "CLI for API generated by cdd-ts",
		);

		let extraHelp = "";
		if (info.contact) {
			extraHelp += `${ESCAPED_NEWLINE}Contact: ${info.contact.name || ""} ${info.contact.email || ""} ${info.contact.url || ""}`;
		}
		if (info.license) {
			extraHelp += `${ESCAPED_NEWLINE}License: ${info.license.name || ""} ${info.license.identifier || ""} ${info.license.url || ""}`;
		}
		if (info.termsOfService) {
			extraHelp += `${ESCAPED_NEWLINE}Terms of Service: ${info.termsOfService}`;
		}
		if (spec.externalDocs) {
			extraHelp += `${ESCAPED_NEWLINE}External Docs: ${spec.externalDocs.description || ""} ${spec.externalDocs.url || ""}`;
		}

		cliFile.addVariableStatement({
			declarationKind: VariableDeclarationKind.Const,
			declarations: [
				{
					name: "program",
					initializer: "new Command()",
				},
			],
		});

		cliFile.addStatements((writer: CodeBlockWriter) => {
			writer.writeLine(
				`program.name('${title}').description('${description}').version('${version}');`,
			);
			if (extraHelp) {
				writer.writeLine(`program.addHelpText('after', '${extraHelp}');`);
			}
			this.writeServerOptions(writer, parser);
			this.writeSecurityOptions(writer, parser);
		});

		const grouped = this.groupOperationsByTag(parser.operations);

		for (const [group, ops] of Object.entries(grouped)) {
			const groupCommandVar = `${group.toLowerCase()}Command`;
			cliFile.addVariableStatement({
				declarationKind: VariableDeclarationKind.Const,
				declarations: [
					{
						name: groupCommandVar,
						initializer: `program.command('${group.toLowerCase()}').description('Commands for ${group}')`,
					},
				],
			});

			this.emitGroupCommands(cliFile, group, groupCommandVar, ops);
		}

		cliFile.addStatements((writer: CodeBlockWriter) => {
			writer
				.writeLine("program.command('mcp')")
				.indent(() => {
					writer.writeLine(
						".description('Start Model Context Protocol (MCP) server over stdio')",
					);
					writer.writeLine(".action(async () => {");
					writer.indent(() => {
						writer.writeLine("const { serveMcp } = await import('./mcp.js');");
						writer.writeLine("await serveMcp();");
					});
					writer.writeLine("});");
				})
				.blankLine()
				.writeLine("program.parse(process.argv);");
		});

		cliFile.saveSync();
	}

	/**
	 * Writes Commander `.option()` calls for OpenAPI server URLs and server variables.
	 *
	 * @param writer - The `ts-morph` `CodeBlockWriter`.
	 * @param parser - The parsed OpenAPI specification.
	 */
	private writeServerOptions(
		writer: CodeBlockWriter,
		parser: SwaggerParser,
	): void {
		const spec = parser.spec;
		if (!spec.servers || spec.servers.length === 0) {
			return;
		}
		writer.writeLine(
			`program.option('--server <url>', 'Override base server URL', '${spec.servers[0].url}');`,
		);
		for (const server of spec.servers) {
			if (!server.variables) continue;
			for (const [varName, variable] of Object.entries(server.variables)) {
				const varDesc = escapeSingleQuotes(
					variable.description || `Server variable ${varName}`,
				);
				writer.writeLine(
					`// Server variable: ${varName} (enum: ${variable.enum?.join(",")}) - ${variable.description || ""}`,
				);
				writer.writeLine(
					`program.option('--server-var-${varName} <value>', '${varDesc}', '${variable.default || ""}');`,
				);
			}
		}
	}

	/**
	 * Writes Commander `.option()` and `.addHelpText()` calls for OpenAPI security schemes.
	 *
	 * @param writer - The `ts-morph` `CodeBlockWriter`.
	 * @param parser - The parsed OpenAPI specification.
	 */
	private writeSecurityOptions(
		writer: CodeBlockWriter,
		parser: SwaggerParser,
	): void {
		const securitySchemes = parser.spec.components?.securitySchemes;
		if (!securitySchemes) {
			return;
		}
		for (const [name, scheme] of Object.entries(securitySchemes)) {
			const s = scheme as SecurityScheme;
			if (s.type === "http" || s.type === "apiKey") {
				writer.writeLine(
					`program.option('--auth-${name.toLowerCase()} <token>', '${escapeSingleQuotes(s.description || `Authentication token for ${name}`)}');`,
				);
			} else if (s.type === "oauth2") {
				writer.writeLine(
					`// OAuth2 Flows supported: ${Object.keys(s.flows || {}).join(", ")}`,
				);
				writer.writeLine(
					`program.option('--auth-${name.toLowerCase()} <token>', '${escapeSingleQuotes(s.description || "OAuth2 token")}');`,
				);
				if (s.oauth2MetadataUrl) {
					writer.writeLine(`// OAuth2 Metadata: ${s.oauth2MetadataUrl}`);
				}
			} else if (s.type === "openIdConnect") {
				writer.writeLine(`// OpenID Connect URL: ${s.openIdConnectUrl}`);
				writer.writeLine(
					`program.option('--auth-${name.toLowerCase()} <token>', '${escapeSingleQuotes(s.description || "OIDC token")}');`,
				);
			}
			if (s.deprecated) {
				writer.writeLine(`// Deprecated security scheme: ${name}`);
				writer.writeLine(
					`program.addHelpText('after', '${ESCAPED_NEWLINE}[DEPRECATED] Security scheme ${name} is deprecated.');`,
				);
			}
		}
	}

	/**
	 * Groups parsed operations by their primary tag name.
	 *
	 * @param operations - Array of parsed OpenAPI operations.
	 * @returns Record mapping group names to their operations.
	 */
	private groupOperationsByTag(
		operations: PathInfo[],
	): Record<string, PathInfo[]> {
		return operations.reduce((acc: Record<string, PathInfo[]>, op) => {
			const group = op.tags?.[0]
				? typeof op.tags[0] === "string"
					? op.tags[0]
					: (op.tags[0] as object as { name?: string }).name ||
						String(op.tags[0])
				: "Default";

			if (!acc[group]) acc[group] = [];
			acc[group].push(op);
			return acc;
		}, {});
	}

	/**
	 * Emits subcommand chains on a tag group command variable for each operation in the group.
	 *
	 * @param cliFile - Target `SourceFile`.
	 * @param group - Tag group name.
	 * @param groupCommandVar - Identifier of the group `Command` variable.
	 * @param ops - Operations belonging to the group.
	 */
	private emitGroupCommands(
		cliFile: SourceFile,
		group: string,
		groupCommandVar: string,
		ops: PathInfo[],
	): void {
		const serviceName = `${group}Service`;

		cliFile.addStatements((writer: CodeBlockWriter) => {
			for (const op of ops) {
				const methodName =
					op.operationId || op.path.replace(/\//g, "_").replace(/^_/, "");
				const commandName = snakeCase(methodName);
				const opDesc = escapeSingleQuotes(op.summary || op.description || "");

				writer.writeLine(`${groupCommandVar}.command('${commandName}')`);
				writer.writeLine(`    .description('${opDesc}')`);

				if (op.externalDocs) {
					writer.writeLine(
						`    .addHelpText('after', '${ESCAPED_NEWLINE}External Docs: ${op.externalDocs.description || ""} ${op.externalDocs.url || ""}')`,
					);
				}

				if (op.deprecated) {
					writer.writeLine("    // Deprecated operation");
					writer.writeLine(
						"    .addHelpText('before', 'Warning: This operation is deprecated.')",
					);
				}

				if (op.callbacks) {
					writer.writeLine("    // Supports Callbacks");
				}

				const optionsAdded = new Set<string>();
				if (op.parameters) {
					for (const param of op.parameters) {
						const pName = (param as Parameter).name;
						if (!pName || optionsAdded.has(pName)) continue;
						optionsAdded.add(pName);
						const requiredFlag = (param as Parameter).required
							? "<value>"
							: "[value]";
						const pDesc = escapeSingleQuotes(
							(param as Parameter).description || "",
						);
						writer.writeLine(
							`    .option('--${pName} ${requiredFlag}', '${pDesc}')`,
						);
					}
				}

				if (op.requestBody) {
					writer.writeLine(
						"    .option('--body <json>', 'Request body (JSON)')",
					);
				}

				writer.writeLine("    .action(async (options) => {");
				writer.indent(() => {
					if (op.deprecated) {
						writer.writeLine(
							`console.warn('[DEPRECATED] Operation ${methodName} is deprecated.');`,
						);
					}
					writer.writeLine(`const client = new services.${serviceName}();`);
					writer.writeLine("try {");
					writer.indent(() => {
						writer.writeLine(
							`const res = await client.${methodName}(options);`,
						);
						writer.writeLine("console.log(JSON.stringify(res, null, 2));");
					});
					writer.writeLine("} catch(err) {");
					writer.indent(() => {
						writer.writeLine("console.error(err);");
						writer.writeLine("process.exit(1);");
					});
					writer.writeLine("}");
				});
				writer.writeLine("    });");
			}
		});
	}
}
